        demand_map = demands
    elif type(demands) == list:
        i = 0
        while i < len(demands):
            demand_map[i] = demands[i]
            i += 1

    if type(instance) == dict and "customers" in instance:
        customers = list(instance["customers"])
    else:
        if coord_map:
            customers = [i for i in coord_map.keys() if i != depot]
        elif demand_map:
            customers = [i for i in demand_map.keys() if i != depot]
        else:
            n = get_first(["n", "num_nodes", "size"], 0)
            try:
                n = int(n)
            except Exception:
                n = 0
            customers = [i for i in range(n) if i != depot]

    customers = sorted(set(customers))

    def demand_of(i):
        v = demand_map.get(i, 0)
        try:
            return float(v)
        except Exception:
            return 0.0

    def coord_of(i):
        return coord_map.get(i, None)

    def dist(a, b):
        ca = coord_of(a)
        cb = coord_of(b)
        if ca is None or cb is None:
            return 0.0
        try:
            ax, ay = ca[0], ca[1]
            bx, by = cb[0], cb[1]
            dx = ax - bx
            dy = ay - by
            return (dx * dx + dy * dy) ** 0.5
        except Exception:
            return 0.0

    try:
        cap = float(capacity)
    except Exception:
        cap = sum(demand_of(i) for i in customers) + 1.0

    total_demand = sum(demand_of(i) for i in customers)
    if cap <= 0:
        cap = total_demand if total_demand > 0 else 1.0

    depot_coord = coord_of(depot)

    def polar_key(i):
        c = coord_of(i)
        if depot_coord is None or c is None:
            return (0, 0, i)
        try:
            dx = c[0] - depot_coord[0]
            dy = c[1] - depot_coord[1]
            q = 0
            if dy < 0:
                q = 1
            if dx < 0:
                q += 2
            r = abs(dx) + abs(dy)
            return (q, r, i)
        except Exception:
            return (0, 0, i)

    ordered = sorted(customers, key=polar_key)
    unassigned = set(customers)
    routes = []

    while unassigned:
        seed = None
        best = None
        for i in ordered:
            if i in unassigned:
                d = demand_of(i)
                if d <= cap:
                    key = (dist(depot, i), d, i)
                    if best is None or key < best:
                        best = key
                        seed = i
        if seed is None:
            seed = min(unassigned)
        route = [seed]
        unassigned.remove(seed)
        load = demand_of(seed)
        current = seed

        while True:
            nxt = None
            best = None
            for j in unassigned:
                d = demand_of(j)
                if load + d <= cap:
                    key = (dist(current, j), d, j)
                    if best is None or key < best:
                        best = key
                        nxt = j
            if nxt is None:
                break
            route.append(nxt)
            unassigned.remove(nxt)
            load += demand_of(nxt)
            current = nxt

        routes.append(route)

    # Repair: move customers from overweight routes if any inconsistent demands exist.
    def route_load(rt):
        s = 0.0
        for x in rt:
            s += demand_of(x)
        return s

    changed = True
    guard = 0
    while changed and guard < 1000:
        guard += 1
        changed = False
        i = 0
        while i < len(routes):
            rt = routes[i]
            if route_load(rt) <= cap + 1e-9:
                i += 1
                continue
            # split overweight route by moving last customers to new routes
            new_rt = []
            new_load = 0.0
            moved = []
            k = 0
            while k < len(rt):
                x = rt[k]
                dx = demand_of(x)
                if new_load + dx <= cap + 1e-9:
                    new_rt.append(x)
                    new_load += dx
                else:
                    moved.append(x)
                k += 1
            if new_rt:
                routes[i] = new_rt
            else:
                routes[i] = [moved[0]]
                moved = moved[1:]
            if moved:
                routes.append(moved)
            changed = True
            i += 1

    # Local search: simple deterministic 2-opt within routes and relocate across routes.
    def route_cost(rt):
        if not rt:
            return 0.0
        c = dist(depot, rt[0])
        j = 0
        while j + 1 < len(rt):
            c += dist(rt[j], rt[j + 1])
            j += 1
        c += dist(rt[-1], depot)
        return c

    improved = True
    rounds = 0
    while improved and rounds < 30:
        rounds += 1
        improved = False

        # Intra-route reversal improvements
        r = 0
        while r < len(routes):
            rt = routes[r]
            n = len(rt)
            best_delta = 0.0
            best_i = -1
            best_j = -1
            base = route_cost(rt)
            i = 0
            while i < n:
                j = i + 1
                while j < n:
                    cand = rt[:i] + rt[i:j+1][::-1] + rt[j+1:]
                    if route_cost(cand) + 1e-12 < base + best_delta:
                        best_delta = route_cost(cand) - base
                        best_i = i
                        best_j = j
                    j += 1
                i += 1
            if best_i >= 0:
                routes[r] = rt[:best_i] + rt[best_i:best_j+1][::-1] + rt[best_j+1:]
                improved = True
            r += 1

        # Relocate single customers if it reduces cost and preserves capacity.
        a = 0
        while a < len(routes):
            b = 0
            while b < len(routes):
                if a != b and routes[a]:
                    ra = routes[a]
                    rb = routes[b]
                    load_b = route_load(rb)
                    i = 0
                    moved_any = False
                    while i < len(ra):
                        x = ra[i]
                        dx = demand_of(x)
                        if load_b + dx <= cap + 1e-9:
                            best_pos = -1
                            best_cost = None
                            base_b = route_cost(rb)
                            pos = 0
                            while pos <= len(rb):
                                cand = rb[:pos] + [x] + rb[pos:]
                                cst = route_cost(cand)
                                if best_cost is None or cst < best_cost:
                                    best_cost = cst
                                    best_pos = pos
                                pos += 1
                            if best_pos >= 0:
                                new_a = ra[:i] + ra[i+1:]
                                new_b = rb[:best_pos] + [x] + rb[best_pos:]
                                if route_cost(new_a) + route_cost(new_b) + 1e-12 < route_cost(ra) + route_cost(rb):
                                    routes[a] = new_a
                                    routes[b] = new_b
                                    ra = routes[a]
                                    rb = routes[b]
                                    load_b += dx
                                    moved_any = True
                                    improved = True
                                    continue
                        i += 1
                    if moved_any:
                        pass
                b += 1
            a += 1

        # Merge route pairs if possible.
        merged = True
        while merged:
            merged = False
            i = 0
            while i < len(routes) and not merged:
                j = i + 1
                while j < len(routes):
                    if route_load(routes[i]) + route_load(routes[j]) <= cap + 1e-9:
                        best_join = routes[i] + routes[j]
                        best_cost = route_cost(best_join)
                        alt = routes[j] + routes[i]
                        alt_cost = route_cost(alt)
                        if alt_cost < best_cost:
                            best_join = alt
                            best_cost = alt_cost
                        if best_cost + 1e-12 < route_cost(routes[i]) + route_cost(routes[j]):
                            routes[i] = best_join
                            del routes[j]
                            merged = True
                            improved = True
                            break
                    j += 1
                if merged:
                    break
                i += 1

    # Final cleanup: remove empty routes and ensure every customer appears once.
    seen = {}
    cleaned = []
    for rt in routes:
        nr = []
        for x in rt:
            if x != depot and x not in seen:
                seen[x] = 1
                nr.append(x)
        if nr:
            cleaned.append(nr)

    missing = [i for i in customers if i not in seen]
    for x in missing:
        cleaned.append([x])

    return cleaned
